BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=pg_catalog,public,extensions,pg_temp;
SELECT no_plan();
SELECT has_table('public','consulting_client_diagnostics','diagnóstico por cliente disponível');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.consulting_client_diagnostics'::regclass),'RLS ativada');
SELECT ok(NOT has_table_privilege('authenticated','public.consulting_client_diagnostics','SELECT'),'sem leitura direta');
SELECT ok(NOT has_table_privilege('authenticated','public.consulting_client_diagnostics','INSERT,UPDATE,DELETE'),'sem escrita direta');
SELECT ok(NOT has_table_privilege('anon','public.consulting_client_diagnostics','SELECT'),'sem leitura anônima');
SELECT ok(NOT has_table_privilege('service_role','public.consulting_client_diagnostics','SELECT'),'sem leitura via service role');
SELECT ok(NOT has_function_privilege('authenticated','public.consulting_diagnostic_access(uuid,boolean)','EXECUTE'),'helper interno');
SELECT ok(has_function_privilege('authenticated','public.read_consulting_client_diagnostic(uuid,uuid)','EXECUTE'),'consulta autenticada');
SELECT ok(has_function_privilege('authenticated','public.save_consulting_client_diagnostic(uuid,uuid,jsonb,integer)','EXECUTE'),'gravação autenticada');
SELECT ok(NOT has_function_privilege('anon','public.read_consulting_client_diagnostic(uuid,uuid)','EXECUTE'),'consulta não pública');
SELECT ok(NOT has_function_privilege('service_role','public.save_consulting_client_diagnostic(uuid,uuid,jsonb,integer)','EXECUTE'),'gravação exige sessão de equipe');
SELECT ok((SELECT provolatile='s' FROM pg_proc WHERE oid='public.read_consulting_client_diagnostic(uuid,uuid)'::regprocedure),'leitura stable');
SELECT ok((SELECT bool_and(proconfig @> ARRAY['search_path=""']) FROM pg_proc WHERE oid IN ('public.read_consulting_client_diagnostic(uuid,uuid)'::regprocedure,'public.save_consulting_client_diagnostic(uuid,uuid,jsonb,integer)'::regprocedure,'public.consulting_diagnostic_access(uuid,boolean)'::regprocedure)),'search path fixo');
SELECT throws_ok($$ SELECT public.read_consulting_client_diagnostic('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002') $$,'42501','CONSULTING_DIAGNOSTIC_ACCESS_DENIED','sem sessão não consulta');
SELECT * FROM finish();
ROLLBACK;
